/* ---------- Comments ---------- */
/* a thread on one spot of a design: the first comment, then its replies indented on a thin line. Each comment is an avatar,
   a name, a time and the text; its Agree button shows on hover or keyboard focus (always, on a touch screen) */
.cmx{padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-4);min-height:340px}
/* on a card the thread keeps the room its last reply takes, so it stays centred while replies arrive */
.stage-in>.cmx{min-height:inherit}
.cmx-h{display:flex;align-items:center;gap:var(--s-2);font-size:13.5px;margin:calc(-1 * var(--s-1)) calc(-1 * var(--s-1)) 0 0}
.cmx-h b{font-weight:500}
.cmx-st{flex:1;font-size:12px;color:var(--muted)}
.cmx-pin{width:20px;height:20px;border-radius:50% 50% 50% var(--r-xs);background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font-size:11px;font-weight:500;flex:none;transition:background var(--t)}
.cmx.done .cmx-pin{background:var(--ok);color:var(--surface)}
.cmx-res{width:28px;height:28px;color:var(--muted)}
.cmx-th{display:flex;flex-direction:column;gap:var(--s-4);flex:1}
.cmx-rp{display:flex;flex-direction:column;gap:var(--s-4);margin-left:var(--s-3);padding-left:calc(var(--s-5) + 1px);position:relative}
/* the replies' line starts just below the first comment's avatar, centred under it, and runs down beside every reply */
.cmx-th>.cmx-c:first-child{position:relative}
.cmx-th>.cmx-c:first-child:has(+ .cmx-rp)::before,.cmx-rp::before{content:'';position:absolute;width:1px;background:var(--rail);pointer-events:none}
.cmx-th>.cmx-c:first-child:has(+ .cmx-rp)::before{left:calc(var(--s-3) - .5px);top:calc(24px + var(--s-1));bottom:calc(-1 * var(--s-4))}
.cmx-rp::before{left:-.5px;top:0;bottom:0}
.cmx-c{display:flex;gap:var(--s-3);min-width:0}
.cmx-c .av{width:24px;height:24px;font-size:10px}
.cmx-c .b{flex:1;display:flex;flex-direction:column;min-width:0}
.cmx-c .n{display:flex;align-items:center;gap:var(--s-2);height:24px;font-size:13px}
.cmx-c .n b{font-weight:500;white-space:nowrap}
.cmx-c .n .t{font-size:12px;color:var(--muted)}
.cmx-c .tx{font-size:13.5px;line-height:1.5;color:var(--fg);overflow-wrap:anywhere}
.cmx-c .m{color:var(--accent-fg,var(--accent));background:var(--sel);border-radius:var(--r-xs);padding:0 2px}
.cmx-c.ag .tx .w{animation:cmw .4s var(--ease) both}
@keyframes cmw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.cmx-c .act{display:flex;flex-wrap:wrap;gap:var(--s-2);margin-top:var(--s-2)}
/* the quiet Agree button beside the time */
.cmx-tools{margin-left:auto;display:flex;gap:var(--s-1);transition:opacity var(--t-fast)}
.cmx-tools .ib{width:26px;height:26px;color:var(--muted)}
.cmx-tools .ib[aria-pressed="true"]{color:var(--fg)}
@media (hover:hover) and (pointer:fine){.cmx-tools{opacity:0}}
.cmx-c .n:focus-within .cmx-tools{opacity:1}
@media (hover:hover) and (pointer:fine){.cmx-c:hover .cmx-tools{opacity:1}}
/* how many agreed: a small chip under the text, a step stronger once you have */
.cmx-rs{display:flex;margin-top:var(--s-2)}
.cmx-rs:has(.cmx-rc[hidden]){display:none}
.cmx-rc{display:inline-flex;align-items:center;gap:var(--s-1);height:22px;padding:0 var(--s-2);border-radius:var(--r-pill);font-size:12px;color:var(--fg2);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--line) 50%,transparent);transition:box-shadow var(--t-fast),color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.cmx-rc:hover{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--rail) 50%,transparent)}}
.cmx-rc[aria-pressed="true"]{color:var(--fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--faint) 50%,transparent)}
/* the reply field: a dimmed edge at rest, one step stronger while it has the focus, and no ring */
.cmx-in{position:relative}
.cmx-box{display:flex;align-items:center;gap:6px;height:var(--field-h);padding:0 5px 0 var(--s-3);border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.cmx-box{corner-shape:squircle;border-radius:var(--r-field-sq)}}
.cmx-box:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.cmx-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--fg)}
.cmx-box input::placeholder{color:var(--muted)}
.cmx-go{width:30px;height:30px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;flex:none;transition:background var(--t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.cmx-go:hover{background:var(--accent-2)}}
.cmx-go:active{transform:scale(.94)}
.cmx-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dis-hatch),var(--dis-fill);color:var(--dis);box-shadow:var(--soft-ring);transform:none}
@media (hover:hover) and (pointer:fine){.cmx-go[disabled]:hover{opacity:1;cursor:not-allowed;background:var(--dis-hatch),var(--dis-fill);color:var(--dis);box-shadow:var(--soft-ring);transform:none}}
.cmx-men{bottom:46px;left:0;min-width:210px}
.cmx.done .cmx-th,.cmx.done .cmx-in{opacity:.45;pointer-events:none;transition:opacity .4s}
.cmx-rv{font-size:12.5px;color:var(--ok);display:flex;align-items:center;gap:6px}
:root:not([data-style="soft"]) .cmx-c .m:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 -1px 0 var(--accent-mark)}

DM.def('comments', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{check}', I('check','xs')).replace('{up}', I('up','xs'));
  const root = $('.cmx', r), th = $('.cmx-th', r), inp = $('.cmx-box input', r), go = $('.cmx-go', r), men = $('.cmx-men', r), st = $('.cmx-st', r), rs = $('.cmx-res', r);
  const P = { MK:['Maya Kim','var(--pl)'], JO:['Jon Ortiz','var(--pm)'], DA:['Design agent','var(--pb)'] };
  const esc = t => t.replace(/[&<>"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' })[ch]);
  const fmt = t => esc(t).replace(/@(agent|maya|jon)\b/gi, m => `<span class="m">${m}</span>`);
  // the first comment starts the thread; every later one is a reply, indented on a thin line under it
  let rp = null;
  const count = () => { const n = rp ? rp.children.length : 0; st.textContent = root.classList.contains('done') ? 'Resolved' : n ? n + (n === 1 ? ' reply' : ' replies') : ''; };
  function add(who, t, when, ag, agreed = 0){
    const el = html(`<div class="cmx-c${ag ? ' ag' : ''}">${AV(who, P[who][1])}<div class="b"><div class="n"><b>${P[who][0]}</b><span class="t">${when}</span><div class="cmx-tools"><button class="ib cmx-rx" aria-label="Agree" aria-pressed="false" data-tip="Agree">${I('up-thumb','xs')}</button></div></div><div class="tx">${ag ? '' : fmt(t)}</div><div class="cmx-rs"><button class="cmx-rc" aria-pressed="false" hidden>${I('up-thumb','xs')}<span class="num"></span></button></div></div></div>`);
    el._agree = { n:agreed, mine:false }; agree(el);
    $('.cmx-rx', el).onclick = () => agree(el, true); $('.cmx-rc', el).onclick = () => agree(el, true);
    if (!th.firstElementChild) th.appendChild(el);
    else { if (!rp){ rp = html('<div class="cmx-rp" role="group" aria-label="Replies"></div>'); th.appendChild(rp); } rp.appendChild(el); }
    enter(el); count(); return el;
  }
  // Agree: the button by the time and the chip under the text both toggle yours, and the chip counts everyone's
  function agree(el, flip){
    const a = el._agree; if (flip) a.mine = !a.mine;
    const n = a.n + (a.mine ? 1 : 0), b = $('.cmx-rx', el), chip = $('.cmx-rc', el), had = document.activeElement === chip;
    b.setAttribute('aria-pressed', a.mine); chip.setAttribute('aria-pressed', a.mine);
    chip.setAttribute('aria-label', 'Agree, ' + n + (n === 1 ? ' person' : ' people') + (a.mine ? ', including you' : ''));
    $('.num', chip).textContent = n; chip.hidden = !n;
    if (had && !n) b.focus({ preventScroll:true });
  }
  add('MK', 'The secondary button feels too faint next to the CTA.', '2h', false, 1);
  add('JO', 'Agree. Can we keep it outlined though?', '1h');
  async function agent(q){
    const el = add('DA', '', 'now', true), tx = $('.tx', el); tx.innerHTML = '<span class="think on" style="color:var(--accent-mark,var(--accent))"><i></i><i></i><i></i><i></i></span>'; await c.wait(900); tx.innerHTML = '';
    const a = /outline|border/i.test(q + ' outlined') ? 'Kept it outlined and raised the text to #5B6472, which passes AA at 5.9 : 1. Want me to apply it to the other 2 frames?' : 'On it. I will post the change here when it is ready.';
    for (const w of a.split(' ')){ tx.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(40); }
    const act = html(`<div class="act"><button class="pill primary sm">Apply to all</button><button class="pill line sm">Just this one</button></div>`); $('.b', el).appendChild(act); enter(act);
    $$('button', act).forEach((b, i) => b.onclick = () => { act.innerHTML = `<span class="cmx-rv">${I('ok','xs')}${i ? 'Applied to frame 2' : 'Applied to 3 frames'}</span>`; enter(act.firstChild); });
  }
  function send(){ const v = inp.value.trim(); if (!v) return; add('MK', v, 'now'); inp.value = ''; go.disabled = true; shut(); if (/@agent/i.test(v)) c.run(() => agent(v)); }
  const opts = [['DA','agent','Design agent'],['MK','maya','Maya Kim'],['JO','jon','Jon Ortiz']];
  // the reply box drives the list of people to mention: it is a combobox, and the highlighted row is its active option
  men.id = 'cmx-m-' + Math.random().toString(36).slice(2, 7); men.setAttribute('aria-label', 'Mention');
  inp.setAttribute('role', 'combobox'); inp.setAttribute('aria-autocomplete', 'list'); inp.setAttribute('aria-expanded', 'false'); inp.setAttribute('aria-controls', men.id);
  let hl = 0;
  const mens = () => $$('.mi', men);
  const light = k => { const all = mens(); if (!all.length){ inp.removeAttribute('aria-activedescendant'); return; } hl = (k + all.length) % all.length; all.forEach((b, j) => { b.classList.toggle('hl', j === hl); b.setAttribute('aria-selected', j === hl); }); inp.setAttribute('aria-activedescendant', all[hl].id); };
  const shut = () => { men.classList.remove('open'); inp.setAttribute('aria-expanded', 'false'); inp.removeAttribute('aria-activedescendant'); };
  inp.oninput = () => { go.disabled = !inp.value.trim(); const m = inp.value.match(/@(\w*)$/);
    if (m){ const list = opts.filter(o => o[1].startsWith(m[1].toLowerCase())); men.innerHTML = list.map(o => `<button class="mi" role="option" tabindex="-1" id="${men.id}-${o[1]}" data-h="${o[1]}">${AV(o[0], P[o[0]][1]).replace('class="av" style="', 'class="av" style="width:20px;height:20px;font-size:9px;')}<span>${o[2]}<span class="d">@${o[1]}</span></span></button>`).join(''); men.classList.toggle('open', list.length > 0); inp.setAttribute('aria-expanded', list.length > 0); light(0);
      $$('.mi', men).forEach(b => b.onmousedown = e => { e.preventDefault(); inp.value = inp.value.replace(/@\w*$/, '@' + b.dataset.h + ' '); shut(); go.disabled = false; inp.focus({ preventScroll:true }); }); }
    else shut(); };
  // with the mention list open, the up and down arrows move through it and wrap, Enter picks, and Escape closes it
  inp.onkeydown = e => {
    const open = men.classList.contains('open') && mens().length;
    if (open && (e.key === 'ArrowDown' || e.key === 'ArrowUp')){ e.preventDefault(); light(hl + (e.key === 'ArrowDown' ? 1 : -1)); return; }
    if (e.key === 'Enter'){ const f = mens()[hl]; if (open && f){ f.onmousedown(e); } else send(); }
    if (e.key === 'Escape') shut(); };
  go.onclick = send;
  // Resolve fades the thread back and turns the pin green; pressed again it reopens
  rs.onclick = () => { const d = root.classList.toggle('done'); hideTip(); rs.innerHTML = I(d ? 'undo' : 'check', 'xs'); rs.setAttribute('aria-pressed', d); rs.dataset.tip = d ? 'Reopen thread' : 'Resolve thread'; count(); };
  // the preview asks the agent in the thread on its own; clicking, focusing or typing in it takes over, and what it had
  // typed goes
  c.auto(1000, () => c.run(async () => { await c.type(inp, '@agent can you keep it outlined but darker?', { ms:28, each:() => inp.oninput(), keep:true }); shut(); await c.step(300); send(); }));
});
